package dev.awc.nativeui

import org.junit.Assert.*
import org.junit.Test
import kotlin.math.*

class NativeLoadingIndicatorContractTest {
    @Test fun hooksCascadeAndRejectInvalidValuesWithoutLosingZeroOrAlpha() {
        val base=AWCLoadingIndicatorAppearance(size=63.5,color="#12345680",containerShape=AWCCornerShape.uniform(fraction=.25))
        val a=base.merged(AWCLoadingIndicatorAppearance(shapeSize=0.0,containerColor="#abcdef"))
        assertEquals(63.5,a.size); assertEquals(0.0,a.shapeSize); assertEquals("#12345680",a.color)
        assertEquals("#ABCDEF",a.containerColor); assertEquals(base.containerShape,a.containerShape)
        for(key in listOf("size","shapeSize")) for(value in listOf(-1,true,"4",Double.NaN,Double.POSITIVE_INFINITY))
            assertEquals(AWCLoadingIndicatorAppearance(),AWCLoadingIndicatorAppearance.fromValues(mapOf(key to value)))
        assertEquals(1e308,AWCLoadingIndicatorAppearance(size=1e308).normalized().size)
        assertNull(AWCCornerShape.fromValues(mapOf("unknown" to 1)))
        assertNull(AWCCornerShape.fromValues(mapOf("topLeft" to null)))
        assertNull(AWCCornerShape.fromValues(mapOf("topLeft" to mapOf("x" to null))))
        assertNull(AWCCornerShape.fromValues(mapOf("topLeft" to mapOf("x" to mapOf("points" to Double.NaN)))))
    }
    @Test fun densitySizeAndIndependentPartKeepCssFlexShrinkAndOverflow() {
        fun metrics(props:Props=emptyMap(),a:AWCLoadingIndicatorAppearance=AWCLoadingIndicatorAppearance(),part:AWCLoadingIndicatorShapeAppearance=AWCLoadingIndicatorShapeAppearance(),density:Double=0.0)=LoadingIndicatorMetrics.from(props,a,part,density)
        for(d in 0 downTo -4) assertEquals((48+4*d).toDouble(),metrics(mapOf("density" to d)).size,.0)
        assertEquals(42.0,metrics(density=-1.5).size,.0)
        assertEquals(32.0,metrics(mapOf("density" to 0),density=-4.0).size,.0)
        assertEquals(40.0,metrics(mapOf("density" to -2),density=-4.0).size,.0)
        assertEquals(LoadingIndicatorMetrics(24.0,24.0,80.0),metrics(a=AWCLoadingIndicatorAppearance(size=24.0,shapeSize=80.0)))
        assertEquals(LoadingIndicatorMetrics(48.0,20.0,30.0),metrics(part=AWCLoadingIndicatorShapeAppearance(width=20.0,height=30.0)))
        assertEquals(LoadingIndicatorMetrics(0.0,0.0,0.0),metrics(a=AWCLoadingIndicatorAppearance(size=0.0)))
        assertEquals(38.016,metrics().shapeWidth,.000001)
    }
    @Test fun physicalEllipticalCornersUseOneOverlapFactorAndFiniteExtremeArithmetic() {
        val corner=AWCCornerRadius(AWCCornerLength(10.0),AWCCornerLength(20.0))
        assertEquals(List(4){10.0 to 20.0},AWCCornerShape(corner,corner,corner,corner).radii(48.0,48.0))
        assertEquals(List(4){24.0 to 24.0},AWCCornerShape.uniform(fraction=1.5).radii(48.0,48.0))
        assertEquals(List(4){22.0 to 22.0},AWCCornerShape.uniform(points=-2.0,fraction=.5).radii(48.0,48.0))
        val huge=AWCCornerShape.uniform(points=1e308,fraction=1e308).radii(48.0,48.0)
        huge.forEach { assertEquals(24.0,it.first,.000001);assertEquals(24.0,it.second,.000001) }
        val top=AWCCornerRadius(AWCCornerLength(1e308),AWCCornerLength(2.0))
        val bottom=AWCCornerRadius(AWCCornerLength(5e307),AWCCornerLength(4.0))
        val scaled=AWCCornerShape(top,top,bottom,bottom).radii(48.0,48.0)
        assertEquals(24.0,scaled[0].first,.000001);assertEquals(12.0,scaled[2].first,.000001)
        assertTrue(scaled.all { it.first.isFinite() && it.second.isFinite() })
        assertEquals(List(4){0.0 to 0.0},AWCCornerShape.uniform(fraction=1e308).radii(0.0,0.0))
    }
    @Test fun reducedMotionIsCircularOpacityPulseWithExactSourcePeriodFractions() {
        for((fraction,opacity) in listOf(0.0 to 1.0,.25 to .7,.5 to .4,.75 to .7,1.0 to 1.0))
            assertEquals(opacity,LoadingIndicatorMotion.reducedOpacity(fraction),.000001)
    }
