    private fun verify(fraction:Double,coordinates:DoubleArray,matrix:DoubleArray) {
        val frame=LoadingIndicatorMotion.at(fraction)
        assertEquals(48,frame.vertices.size)
        frame.vertices.forEachIndexed { i,p -> assertEquals("$fraction vertex$i x",coordinates[i*2],p.first,.000001);assertEquals("$fraction vertex$i y",coordinates[i*2+1],p.second,.000001) }
        val angle=frame.rotation*PI/180
        assertEquals("$fraction cos",matrix[0],cos(angle),.000002);assertEquals("$fraction sin",matrix[1],sin(angle),.000002)
    }
